import type {MetadataRoute} from "next";import {GAME_IDENTITIES} from "@/lib/seed";export default function sitemap():MetadataRoute.Sitemap{const base=process.env.NEXT_PUBLIC_SITE_URL??"http://localhost:3000";const staticRows=["","/games","/rising","/methodology"].map(path=>({url:`${base}${path}`,lastModified:new Date(),changeFrequency:"daily" as const,priority:path===""?1:.7}));const games=GAME_IDENTITIES.filter(g=>g.indexState==="indexable").map(g=>({url:`${base}/game/${g.slug}`,lastModified:new Date(),changeFrequency:"daily" as const,priority:.8}));return[...staticRows,...games];}
